CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF current_setting('app.skip_updated_at', true) = 'on' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW."updatedAt" IS NULL THEN
      NEW."updatedAt" = now();
    END IF;
  ELSE
    NEW."updatedAt" = now();
  END IF;
  RETURN NEW;
END;
$function$
